use crate::exec::{self, ExecResult};

#[test]
fn test_exec_allowed() {
    let exec_res = exec::run("echo hello");
    assert!(!exec_res.allowed);
}

#[test]
fn test_exec_denied() {
    let exec_res = exec::run("rm -rf /");
    assert!(exec_res.denied);
